contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        bool withdrawReverted;
        c.withdraw{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        bool commandReverted;
        c.Command{value: amount}(address(0x1234), new bytes(0)); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            commandReverted = true;
        } else {
            commandReverted = false;
        }

        assert(withdrawReverted == commandReverted);
    }
}

